let margin = 3;
let N = 24;
let u, maxSize = 7;

let randInt = (a, b) => (floor(random(a, b))); 

function setup() {
  createCanvas(600, 600);
	u = width / N;
	gap = u / 4;
}

function draw() {
	background(0);
	blendMode(ADD);

	let colors = [[255, 0, 0], [0, 255, 0], [0, 0, 255]];

	for (let c of colors) {
		fill(c);
		let squares = createComposition();
		for (let squ of squares) {
			square(squ.i*u+gap/2, squ.j*u+gap/2, squ.s*u-gap, random([(u-gap)/2, u*maxSize]));
		}
	}

	// noLoop() removed for animation
}

function createComposition() {
	var squares = [];
	for (let i = 0; i < 500; i++) {
    let newSqu = generateSquare();
    let canAdd = true;
    for (let squ of squares) {
      if (squaresIntersect(newSqu, squ)) {
        canAdd = false;
        break;
      }
    }
    if (canAdd) {
      squares.push(newSqu);
    }
  }

  // fill the gaps with 1x1 squares
	for (let i = margin; i < N-margin; i++) {
		for (let j = margin; j < N-margin; j++) {
			var newSqu = {
				i: i,
				j: j,
				s: 1
			}
			var canAdd = true;
			for (let squ of squares) {
				if (squaresIntersect(newSqu, squ)) {
					canAdd = false;
					break;
				}
			}
			if (canAdd) {
				squares.push(newSqu);
			}
		}
	}

	return squares;
}

function squaresIntersect(squ1, squ2) {
	return ((squ1.i <= squ2.i && squ1.i+squ1.s > squ2.i) || (squ2.i <= squ1.i && squ2.i+squ2.s > squ1.i)) && ((squ1.j <= squ2.j && squ1.j+squ1.s > squ2.j) || (squ2.j <= squ1.j && squ2.j+squ2.s > squ1.j))
}

function generateSquare() {
  let s = randInt(2, maxSize);
  let i = randInt(margin, N-margin-s+1);
  let j = randInt(margin, N-margin-s+1);
  let squ = {
    i: i,
    j: j,
    s: s
  };
  return squ;
}
